import java.util.ArrayList;
import java.util.List;

public class Ex01DynamicSqlWhere {

    // 复刻 <where>：内容非空才加 WHERE，并去掉前导 AND / OR
    static class WhereTag {
        private final List<String> parts = new ArrayList<String>();

        void append(String fragment, boolean cond) {
            if (cond) {
                parts.add(fragment);
            }
        }

        boolean isEmpty() {
            return parts.isEmpty();
        }

        String render() {
            if (parts.isEmpty()) {
                return "";
            }
            String body = String.join(" ", parts).trim();
            body = body.replaceFirst("(?i)^(AND|OR)\\s+", "");
            return "WHERE " + body;
        }
    }

    // 反例：不做修剪的直接拼接（等价于 SELECT ... WHERE ${动态段}）
    static class NaiveWhere {
        private final List<String> parts = new ArrayList<String>();

        void append(String fragment, boolean cond) {
            if (cond) {
                parts.add(fragment);
            }
        }

        String render() {
            if (parts.isEmpty()) {
                return "WHERE";
            }
            return "WHERE " + String.join(" ", parts);
        }
    }

    static boolean danglingOperator(String sql) {
        return sql.matches("(?is).*\\bWHERE\\s+(AND|OR)\\b.*");
    }

    static String show(String s) {
        return s.isEmpty() ? "<empty>" : s;
    }

    public static void main(String[] args) {
        // 情形一：两个条件都成立
        WhereTag w1 = new WhereTag();
        w1.append("name = ?", true);
        w1.append("AND status = ?", true);
        NaiveWhere n1 = new NaiveWhere();
        n1.append("name = ?", true);
        n1.append("AND status = ?", true);
        System.out.println("case1 naive        : " + n1.render());
        System.out.println("case1 where        : " + w1.render());

        // 情形二：第一个条件不成立，首个保留片段以 AND 开头
        WhereTag w2 = new WhereTag();
        w2.append("name = ?", false);
        w2.append("AND status = ?", true);
        NaiveWhere n2 = new NaiveWhere();
        n2.append("name = ?", false);
        n2.append("AND status = ?", true);
        System.out.println("case2 naive        : " + n2.render());
        System.out.println("case2 where        : " + w2.render());
        System.out.println("case2 naive broken : " + danglingOperator(n2.render()));
        System.out.println("case2 where broken : " + danglingOperator(w2.render()));

        // 情形三：全部条件都不成立，整条 WHERE 不生成
        WhereTag w3 = new WhereTag();
        w3.append("name = ?", false);
        w3.append("AND status = ?", false);
        System.out.println("case3 where        : " + show(w3.render()));
        System.out.println("case3 has WHERE    : " + (!w3.isEmpty()));
        System.out.println("case3 broken       : " + danglingOperator(w3.render()));
    }
}
